/* ==========================================================================
   >>> EDIT THESE <<<
   ========================================================================== */
const SHEET_ID    = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';
const PUBLIC_BASE = 'https://condone-making-amount.ngrok-free.dev';      // n8n, for cancel links
const BOOKING_URL = 'http://localhost:3000';      // the booking page
const CLINIC_NAME = 'Smile Dental Clinic';
const TIMEZONE    = 'Asia/Karachi';
const PHONE_MATCH_DIGITS = 10;   // compare the last N digits (10 suits PK/IN/UAE/UK)
/* ========================================================================== */

const q = $input.first().json.query || {};
const raw = String(q.phone || '').trim();
if (!raw) throw new Error('Missing "phone"');

// WhatsApp gives 923001234567; a patient may have typed 0300 1234567 or
// +92 300 1234567. Comparing the last N digits makes all of those match
// without us having to guess the country code.
const tail = s => String(s||'').replace(/\D/g,'').slice(-PHONE_MATCH_DIGITS);
const key = tail(raw);
if (key.length < PHONE_MATCH_DIGITS) throw new Error('Phone number too short');

return [{ json: { SHEET_ID, PUBLIC_BASE, BOOKING_URL, CLINIC_NAME, TIMEZONE,
  PHONE_MATCH_DIGITS, phone: raw, key,
  scope: String(q.scope || 'upcoming').toLowerCase() } }];

// --- shared helpers -------------------------------------------------------
const toMin  = t => { const [h,m] = String(t).split(':').map(Number); return h*60 + (m||0); };
const toHHMM = m => `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const parts  = (isoStr, tz) => {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year:'numeric', month:'2-digit',
    day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false });
  const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
};
const prettyDate = (d, tz) => new Date(d + 'T12:00:00Z')
  .toLocaleDateString('en-GB', { timeZone: tz, weekday:'long', day:'numeric', month:'long', year:'numeric' });
const pretty12 = t => { const [h,m] = String(t).split(':').map(Number);
  return `${((h+11)%12)+1}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`; };
const busyBlocks = (fb, calId, day, tz) => {
  const cal = fb.calendars || {};
  const raw = (cal[calId] && cal[calId].busy) || (Object.values(cal)[0] || {}).busy || [];
  const out = [];
  for (const b of raw) {
    const s = parts(b.start, tz), e = parts(b.end, tz);
    if (e.date < day || s.date > day) continue;
    out.push([ s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min ]);
  }
  return out;
};
// --------------------------------------------------------------------------

const c    = $('Config').first().json;
const rows = ($input.first().json.values) || [];
const tail = s => String(s||'').replace(/\D/g,'').slice(-c.PHONE_MATCH_DIGITS);

const off = (() => {
  const s = new Intl.DateTimeFormat('en-US', { timeZone: c.TIMEZONE, timeZoneName: 'longOffset' })
    .formatToParts(new Date()).find(x => x.type === 'timeZoneName').value.replace('GMT','');
  return s || '+00:00';
})();
const now = Date.now();

const mine = [];
for (const r of rows) {
  if (tail(r[9]) !== c.key) continue;                 // column J = phone
  const status = String(r[2] || '').toUpperCase();
  if (status === 'EXPIRED') continue;                 // never happened, don't show it
  const when = Date.parse(`${r[5]}T${r[6]}:00${off}`);
  const upcoming = when > now - 3600000;
  if (c.scope === 'upcoming' && !upcoming) continue;
  if (c.scope === 'past' && upcoming) continue;

  mine.push({
    reference: r[0], status,
    service: r[4], date: r[5], time: r[6],
    when: `${prettyDate(r[5], c.TIMEZONE)} at ${pretty12(r[6])}`,
    durationMin: Number(r[7]) || null,
    name: r[8], price: r[16] || null,
    doctor: String(r[18] || '').trim(), doctorName: String(r[19] || '').trim(),
    upcoming,
    // Safe to hand over: we already proved this phone owns the booking, and the
    // link still shows an "are you sure" page before anything is deleted.
    cancelLink: (status === 'PENDING' || status === 'CONFIRMED')
      ? `${c.PUBLIC_BASE}/webhook/booking-action?ref=${encodeURIComponent(r[0])}&token=${encodeURIComponent(r[13])}&action=cancel`
      : null,
    confirmLink: status === 'PENDING'
      ? `${c.PUBLIC_BASE}/webhook/booking-action?ref=${encodeURIComponent(r[0])}&token=${encodeURIComponent(r[13])}&action=confirm`
      : null
  });
}
mine.sort((a,b) => (a.date+a.time).localeCompare(b.date+b.time));

return [{ json: { phone: c.phone, count: mine.length, bookings: mine,
  message: mine.length ? null : 'No appointments found for this number.' } }];
